/** condensed formula of a chain of n carbons with substituents {pos: group} and a double bond at position dbl (dbl=p means C(p)=C(p+1)) */
function chainText(n, subs, dbl) {
  let out = '';
  for (let i = 1; i <= n; i++) {
    let bonds = (i > 1 ? 1 : 0) + (i < n ? 1 : 0) + (dbl && (i === dbl || i === dbl + 1) ? 1 : 0) + (subs[i] ? 1 : 0);
    const h = 4 - bonds;
    out += h === 0 ? 'C' : h === 1 ? 'CH' : 'CH' + h;
    if (subs[i]) out += `(${subs[i]})`;
    if (dbl && i === dbl) out += '=';
  }
  return out;
}
